-- 비상교육 초5 영어 Lesson 9 재작성 (Flow(5)_수정본.xlsx 기준): 1) 학습 흐름 2) 문항 3) 교과서 자료(QR 음원·영상 스크립트)
-- 기존 L9 흐름·문항·QR 스크립트는 backup_20261120 에 백업한 뒤 지우고, 6차시(1~5 + Check-up)로 다시 만든다. 교과서 스캔 파일(scan)은 건드리지 않는다.
-- 문항은 모두 초안(draft)으로 들어간다 (승인·발행은 따로). content/l9v2 에서 생성.
create schema if not exists backup_20261120;
create table if not exists backup_20261120.items as select * from public.items;
create table if not exists backup_20261120.flow_lessons as select * from public.flow_lessons;
create table if not exists backup_20261120.flow_steps as select * from public.flow_steps;
create table if not exists backup_20261120.unit_sources as select * from public.unit_sources;
revoke all on schema backup_20261120 from anon, authenticated;

do $do$
declare v_unit uuid; v_les uuid; v_n int; v_miss int; l jsonb; s jsonb;
begin
  select u.id into v_unit from units u join books b on b.id = u.book_id where b.title = '비상교육 초5 영어' and u.no = 9;
  if v_unit is null then raise exception 'L9 unit not found'; end if;

  create temp table _col on commit drop as select no, color from flow_lessons where unit_id = v_unit and track = 'core';

  delete from items where unit_id = v_unit;
  delete from flow_lessons where unit_id = v_unit;
  delete from unit_sources where unit_id = v_unit and kind = 'script';

  for l in select * from jsonb_array_elements($j$[{"no":1,"en":"Listen & Learn","ko":"듣고 익혀요","goal":"핵심 단어와 표현의 뜻을 알고 따라 말해요","steps":[{"pos":0,"name_en":"Learning Goal","name_ko":"학습목표","minutes":1,"kind":"goal","qty":1,"homework":false},{"pos":1,"name_en":"Lecture Slides","name_ko":"강의 슬라이드","minutes":3,"kind":"lecture","qty":1,"homework":false},{"pos":2,"name_en":"Word Cards","name_ko":"단어 카드 보기","minutes":2,"kind":"vcards","qty":1,"homework":false},{"pos":3,"name_en":"Word Repeat","name_ko":"단어 듣고 따라 말하기","minutes":3,"kind":"wrepeat","qty":6,"homework":false},{"pos":4,"name_en":"Word-Meaning Choice","name_ko":"단어-뜻 고르기","minutes":3,"kind":"wchoice","qty":6,"homework":false},{"pos":5,"name_en":"Key Expressions","name_ko":"핵심표현 듣고 따라 읽기","minutes":2,"kind":"kexp","qty":1,"homework":false},{"pos":6,"name_en":"Sentence Drill","name_ko":"문장 바꿔 말하기","minutes":3,"kind":"sdrill","qty":4,"homework":true},{"pos":7,"name_en":"Scene Story","name_ko":"장면 영상 보기","minutes":4,"kind":"scene","qty":2,"homework":false},{"pos":8,"name_en":"Scene Story","name_ko":"장면 영상 보기","minutes":4,"kind":"scene","qty":2,"homework":false},{"pos":9,"name_en":"Listen & Choose (Picture)","name_ko":"듣고 고르기 (그림 4칸)","minutes":3,"kind":"lchpic","qty":6,"homework":true},{"pos":10,"name_en":"Word-meaning Match","name_ko":"단어-뜻 짝 맞추기","minutes":2,"kind":"vmatch","qty":1,"homework":true}]},{"no":2,"en":"Listen & Speak","ko":"듣고 말해요","goal":"배운 질문을 듣고 대답하며 말해요","steps":[{"pos":0,"name_en":"Word & Sentence Repeat","name_ko":"단어·문장 듣고 따라 말하기","minutes":3,"kind":"wsent","qty":6,"homework":false},{"pos":1,"name_en":"Tap & Listen","name_ko":"문장 눌러 듣기","minutes":2,"kind":"tapl","qty":1,"homework":false},{"pos":2,"name_en":"Listen & Learn (Text)","name_ko":"듣고 익히기 (글)","minutes":2,"kind":"lcardt","qty":1,"homework":false},{"pos":3,"name_en":"Scene Story + Repeat","name_ko":"장면 영상 보기 + 따라 말하기","minutes":4,"kind":"scenerep","qty":2,"homework":false},{"pos":4,"name_en":"Scene Story + Repeat","name_ko":"장면 영상 보기 + 따라 말하기","minutes":4,"kind":"scenerep","qty":2,"homework":false},{"pos":5,"name_en":"Listen & Match","name_ko":"듣고 짝짓기","minutes":2,"kind":"lmatch","qty":4,"homework":false},{"pos":6,"name_en":"Listen & Choose","name_ko":"듣고 고르기 (글 4칸)","minutes":3,"kind":"lchtext","qty":6,"homework":true},{"pos":7,"name_en":"Listen & Matching (Write)","name_ko":"듣고 짝지어 쓰기","minutes":2,"kind":"lmwrite","qty":4,"homework":false},{"pos":8,"name_en":"Listen & Choose (Number)","name_ko":"듣고 번호 고르기","minutes":3,"kind":"lnum","qty":5,"homework":true},{"pos":9,"name_en":"Role Play","name_ko":"역할 나눠 말하기","minutes":4,"kind":"role","qty":2,"homework":false}]},{"no":3,"en":"Ask & Answer","ko":"묻고 답해요","goal":"질문과 대답을 바꾸어 말하고 모범 글을 익혀요","steps":[{"pos":0,"name_en":"Read Aloud","name_ko":"따라 읽기 평가","minutes":3,"kind":"raloud","qty":11,"homework":false},{"pos":1,"name_en":"Read & Speak (Text)","name_ko":"대화 따라 읽기 (글)","minutes":3,"kind":"dreadt","qty":4,"homework":false},{"pos":2,"name_en":"Sentence Scramble","name_ko":"문장 만들기","minutes":3,"kind":"sscram","qty":6,"homework":false},{"pos":3,"name_en":"Say in English","name_ko":"우리말 보고 영어로 말하기","minutes":3,"kind":"saykor","qty":6,"homework":true},{"pos":4,"name_en":"Look & Speak","name_ko":"그림 보고 말하기","minutes":3,"kind":"lookspeak","qty":6,"homework":true},{"pos":5,"name_en":"Model Text","name_ko":"모범 글 읽기","minutes":2,"kind":"mtext","qty":2,"homework":false},{"pos":6,"name_en":"Story Quiz (T/F)","name_ko":"글 읽고 답하기","minutes":3,"kind":"sqset","qty":2,"homework":false},{"pos":7,"name_en":"Story Cloze","name_ko":"글 빈칸 채우기","minutes":3,"kind":"scloze","qty":3,"homework":false},{"pos":8,"name_en":"Model Writing (Free)","name_ko":"나만의 글 쓰기","minutes":4,"kind":"mfree","qty":2,"homework":false}]},{"no":4,"en":"Read & Understand","ko":"읽고 알아봐요","goal":"배운 표현이 들어간 글을 읽고 이해해요","steps":[{"pos":0,"name_en":"Fill the Blank","name_ko":"빈칸 단어 쓰기","minutes":4,"kind":"sfill","qty":10,"homework":true},{"pos":1,"name_en":"Sentence Build-up (Read & Reply)","name_ko":"문장 만들기 (보고 이어질 말)","minutes":3,"kind":"sscramr","qty":3,"homework":false},{"pos":2,"name_en":"Listen & Speak","name_ko":"듣고 대답하기","minutes":3,"kind":"lspeak","qty":6,"homework":true},{"pos":3,"name_en":"Passage Read Aloud","name_ko":"글 듣고 읽기","minutes":5,"kind":"pread","qty":2,"homework":false},{"pos":4,"name_en":"Passage Read Aloud","name_ko":"글 듣고 읽기","minutes":5,"kind":"pread","qty":2,"homework":false}]},{"no":5,"en":"Master & Expand","ko":"익히고 넓혀요","goal":"모범 글을 참고해 내 글을 쓰고 발표해요","steps":[{"pos":0,"name_en":"Complete the Dialogue (Picture)","name_ko":"대화 완성하기 (그림)","minutes":4,"kind":"dfill","qty":6,"homework":false},{"pos":1,"name_en":"Model Text","name_ko":"모범 글 읽기","minutes":3,"kind":"mtext","qty":2,"homework":false},{"pos":2,"name_en":"Sentence Scramble","name_ko":"문장 만들기","minutes":3,"kind":"sscram","qty":4,"homework":true},{"pos":3,"name_en":"Model Writing (Word Bank)","name_ko":"모범 글 완성 (보기)","minutes":3,"kind":"mwbank","qty":2,"homework":false},{"pos":4,"name_en":"Model Writing (Free)","name_ko":"나만의 글 쓰기","minutes":4,"kind":"mfree","qty":2,"homework":false},{"pos":5,"name_en":"Presentation","name_ko":"발표 영상 찍기","minutes":3,"kind":"present","qty":1,"homework":false},{"pos":6,"name_en":"AI Free Talk","name_ko":"AI 자유대화","minutes":4,"kind":"aitalk","qty":1,"homework":true}]},{"no":6,"en":"Check-up","ko":"점검해요","goal":"배운 표현을 새로운 상황에서 확인해요","steps":[{"pos":0,"name_en":"Picture Writing","name_ko":"그림 보고 쓰기","minutes":3,"kind":"vwrite","qty":6,"homework":false},{"pos":1,"name_en":"Listen & Choose (List)","name_ko":"듣고 고르기 (세로형)","minutes":3,"kind":"lchlist","qty":4,"homework":false},{"pos":2,"name_en":"Listen & Match (Picture)","name_ko":"듣고 그림·글 연결하기","minutes":3,"kind":"lpmatch","qty":4,"homework":false},{"pos":3,"name_en":"Listen & Write (Blank)","name_ko":"듣고 빈칸 쓰기","minutes":3,"kind":"lblank","qty":4,"homework":false},{"pos":4,"name_en":"Look & Talk","name_ko":"그림 보고 대화하기","minutes":3,"kind":"looktalk","qty":4,"homework":true},{"pos":5,"name_en":"Sentence Scramble","name_ko":"문장 만들기","minutes":3,"kind":"sscram","qty":6,"homework":false},{"pos":6,"name_en":"Complete the Dialogue (Text Cue)","name_ko":"대화 완성하기 (글 단서)","minutes":3,"kind":"dfillt","qty":4,"homework":false},{"pos":7,"name_en":"Story Check","name_ko":"글 읽고 답하기","minutes":3,"kind":"sqset","qty":2,"homework":false},{"pos":8,"name_en":"Sentence Build-up","name_ko":"문장 쓰기 (우리말→영어)","minutes":3,"kind":"sbuild","qty":6,"homework":false},{"pos":9,"name_en":"Listen & Choose (Number)","name_ko":"듣고 번호 고르기","minutes":3,"kind":"lnum","qty":4,"homework":true}]}]$j$::jsonb) loop
    insert into flow_lessons(unit_id, no, en, ko, goal, color, track)
      values (v_unit, (l->>'no')::int, l->>'en', l->>'ko', l->>'goal', coalesce((select color from _col where no = (l->>'no')::int), ''), 'core') returning id into v_les;
    for s in select * from jsonb_array_elements(l->'steps') loop
      insert into flow_steps(lesson_id, pos, name_en, name_ko, minutes, kind, qty, homework, study)
        values (v_les, (s->>'pos')::int, s->>'name_en', s->>'name_ko', (s->>'minutes')::int, s->>'kind', (s->>'qty')::int, (s->>'homework')::boolean, true);
    end loop;
  end loop;

  create temp table _l9 on commit drop as
    select * from jsonb_to_recordset($j$[{"lesson":1,"pos":0,"n":0,"kind":"goal","tag":"expr","payload":{"tag":"expr","pic":"socks","k":"goal","title":"가게에서 물건의 가격을 묻고 답하며, 사고 싶은 물건을 말할 수 있어요.","items":[{"en":"How much are these socks?","ko":"이 양말은 얼마예요?","group":"물건의 가격 묻고 답하기"},{"en":"They're two thousand won.","ko":"2,000원이에요.","group":"물건의 가격 묻고 답하기"},{"en":"May I help you?","ko":"도와드릴까요?","group":"도움 제안하고 답하기"},{"en":"Yes, please.","ko":"네, 부탁해요.","group":"도움 제안하고 답하기"}]}},{"lesson":1,"pos":1,"n":0,"kind":"lecture","tag":"expr","payload":{"tag":"expr","k":"lecture","title":"Lesson 9","slides":[{"head":"가게에서는 이렇게 말해요","text":["가게에 가면 점원이 먼저 말을 걸어요.","이번 Lesson에서는 물건의 [[가격]]을 묻고 대답하는 말을 배워요."],"pic":"hat","cards":["May I help you? | 도와드릴까요? | 점원","Yes, please. | 네, 부탁해요. | 손님","How much is this hat? | 이 모자는 얼마예요? | 손님"]},{"head":"도움을 주고받는 표현","text":["[[May I help you?]]는 '도와드릴까요?'라는 뜻이에요.","도움이 필요하면 [[Yes, please.]]라고 대답해요. please가 붙으면 부탁하는 말이라 더 공손해요."],"cards":["May I help you? | 도와드릴까요? | 묻는 말","Yes, please. | 네, 부탁해요. | 대답"]},{"head":"가격 묻고 답하기 ① 하나일 때","text":["얼마인지 물을 때는 [[How much]]로 시작해요.","가까이 있는 물건 하나는 [[this]], 동사는 [[is]]를 써요."],"pic":"jacket","cards":["How much is this jacket? | 이 재킷은 얼마예요?","It's thirty thousand won. | 30,000원이에요."],"formula":["How much + {{is}} + this + 물건?","It's + 가격 + won."]},{"head":"가격 묻고 답하기 ② 여러 개일 때","text":["물건이 여러 개이면 this는 these로, is는 are로, It's는 They're로 바뀌어요."],"pic":"shoes","cards":["How much are these shoes? | 이 신발은 얼마예요?","They're fifty thousand won. | 50,000원이에요."],"formula":["How much + {{are}} + these + 물건들?","They're + 가격 + won."],"tip":"sunglasses, shorts, socks, shoes는 두 개가 한 짝이라서 [[these]]를 써요."},{"head":"This / These, is / are 의 차이","text":["물건이 하나인지 여러 개인지에 따라 말이 달라져요."],"table":["| 하나 | 여러 개","가리킬 때 | this | these","동사 | is | are","대답 | It's | They're"],"tip":"가격은 숫자를 영어로 읽고 뒤에 [[won]]을 붙여요. (ten thousand won = 10,000원)"}]}},{"lesson":1,"pos":2,"n":0,"kind":"vcards","tag":"vocab","payload":{"tag":"vocab","