  select count(*) into v_miss from _l9 d where not exists (
    select 1 from flow_steps s join flow_lessons fl on fl.id = s.lesson_id where fl.unit_id = v_unit and fl.no = d.lesson and s.pos = d.pos and s.kind = d.kind);
  if v_miss > 0 then raise exception 'L9 content: % item(s) do not match a flow step (lesson/pos/kind)', v_miss; end if;

  insert into items(unit_id, lesson, act_idx, level, template, tag, payload, status, step_id, created_at)
  select v_unit, d.lesson, d.pos, 'CORE', d.kind, d.tag, d.payload, 'draft', s.id, now() + (d.n * interval '1 millisecond')
    from _l9 d join flow_lessons fl on fl.unit_id = v_unit and fl.no = d.lesson join flow_steps s on s.lesson_id = fl.id and s.pos = d.pos;
  get diagnostics v_n = row_count;
  if v_n <> (select count(*) from _l9) then raise exception 'L9 content: inserted % of %', v_n, (select count(*) from _l9); end if;

  insert into unit_sources(unit_id, kind, lesson_no, sort, title, body, memo, remark)
  select v_unit, 'script', x.lesson_no, x.sort, x.title, x.body, x.memo, x.remark
    from jsonb_to_recordset($j$[{"lesson_no":1,"sort":1,"title":"음원1","body":"How much is this jacket?\nIt's ten thousand won.","memo":"단원의 주제를 소개하기 위한 영상\n(1차시의 학습목표가 '말을 듣고 이해하기'로 규정)","remark":""},{"lesson_no":1,"sort":2,"title":"음원2","body":"May I help you?\nYes, please\nHow much are these shoes?\nThey're forty thousand won.","memo":"","remark":""},{"lesson_no":1,"sort":3,"title":"영상 (1/2)","body":"Let's buy things for our hiking trip this weekend\nI love shopping\nDad, we can buy things on this note.\nMay I help you\nYes, please\nI'm looking for some shorts.\nWe have many cool shorts here.\nHow about these shorts\nThey're nice.\nI like the color.\nHow much are these shorts?\nThey're 15,000 won.\nGood.\nI'll take them","memo":"","remark":"유사하게 변경 필요"},{"lesson_no":1,"sort":4,"title":"영상 (2/2)","body":"This hat is nice\nIt's only 5,000 won\nLook at these socks.\nThey'll be great for hiking\nI'll take them, too.\n40,000 won?\nHow much are these socks?\nThey're 20,000 won.\n20,000 won for socks?\nOh, no","memo":"","remark":"유사하게 변경 필요"},{"lesson_no":2,"sort":5,"title":"영상1","body":"They're so funny\nLook at these sunglasses.\nThey look like mouse.\nThey're so funny\nMay I try them on?\nSure, go ahead.\nHow much are these sunglasses?\nThey're 3,000 won.\nThey're on sale.\nCool.\nI'll take them.","memo":"Look and speak 영상\n(영상을 보고, 한글로 질문2를 함)\n\n1)민서가 고른 선글라스의 가격은 얼마인가요?\n2) 점원이 Pablo에게 도움을 제안할 때,뭐라고 말했나요?","remark":"유사하게 변경 필요"},{"lesson_no":2,"sort":6,"title":"영상2","body":"May I help you?\nYes, please\nI'm looking for a jacket.\nHow much is this jacket?\nIt's 15,000 won.\nTry on the jacket with these sunglasses.\nWow. You look great.","memo":"","remark":"유사하게 변경 필요"},{"lesson_no":2,"sort":7,"title":"영상3","body":"May I help you?\nYes, please.\nHow much are these socks?\nThey're 2,000 won.","memo":"Speak more 영상 (교재에 있음)","remark":""},{"lesson_no":5,"sort":8,"title":"음원","body":"Hello.\nWe are group one.\nWelcome to the Funny hat shop.\nLook at this cat hat.\nIt has two ears.\nHow much is this hat?\nIt's 10,000 won.\nDo you like this hat?\nThank you very much.","memo":"Watch and think의 샘플영상","remark":"유사하게 변경 필요"},{"lesson_no":6,"sort":9,"title":"1번 음원","body":"<no. 1>\nA : how much is this jacket\nB : it's thirty thousand won.\n<no. 2>\nA : How much are these shoes?\nB: They're fifty thousand won.","memo":"","remark":""},{"lesson_no":6,"sort":10,"title":"2번 음원","body":"<no. 1>\nA : How much is this hat?\nB : It's fifteen thousand won.\n<no. 2>\nA: May I help you\nB: How much are these socks?\nA : They're ten thousand won.","memo":"","remark":""},{"lesson_no":6,"sort":11,"title":"3번 음원","body":"<no. 1>\nA : How much are these sunglasses?\nB : They're twenty thousand won.\n<no. 2>\nA : May I help you\nB : yes please.\nA : How much are these shorts?\nB : They're twenty-five thousand won.","memo":"","remark":""},{"lesson_no":6,"sort":12,"title":"4번 음원","body":"<no. 1>\nA : How much are these shoes?\nB: They're thirty thousand won.\n<no. 2>\nA : How much is this jacket?\nB : It's fifty thousand won.","memo":"","remark":""}]$j$::jsonb) as x(lesson_no int, sort int, title text, body text, memo text, remark text);

  raise notice 'L9 rebuilt: % lessons, % steps, % items (draft), % scripts', (select count(*) from flow_lessons where unit_id = v_unit), (select count(*) from flow_steps s join flow_lessons fl on fl.id = s.lesson_id where fl.unit_id = v_unit), v_n, 12;
end $do$;
